const q = $json.qualificationData || {};
const assigned = (q.assigned_department || '').trim();
// Auto-assign dept if missing (backup to parser logic)
if (!assigned) {
  const cat = (q.issue_category || $json.purpose || '').toLowerCase();
  if (/(login|access|password|reset)/.test(cat)) q.assigned_department = 'Technical Support';
  else if (/(billing|payment|invoice)/.test(cat)) q.assigned_department = 'Billing Team';
  else if (/(setup|configuration|install)/.test(cat)) q.assigned_department = 'Onboarding Support';
  else if (/(account|subscription)/.test(cat)) q.assigned_department = 'Customer Success';
  else q.assigned_department = 'General Support';
}
// Ticket id fallback
if (!q.ticket_id || !String(q.ticket_id).trim()) {
  q.ticket_id = 'SUP-' + Date.now();
}
return { ...$json, qualificationData: q };

// ======================================================
// 🧠 IronClad Family – Final Validate & Normalize (Nested Qualification Schema)
// Ensures all fields are present, fills missing ones, and groups extra info
// ======================================================

// 1️⃣ Parse the OpenAI message content safely
let raw = $json;
let parsed = {};

try {
  if (typeof raw.message?.content === "string") {
    parsed = JSON.parse(raw.message.content);
  } else if (Array.isArray(raw) && typeof raw[0]?.message?.content === "string") {
    parsed = JSON.parse(raw[0].message.content);
  } else {
    parsed = raw;
  }
} catch (err) {
  parsed = raw;
}

// 2️⃣ Core structure (top-level essentials)
const result = {
  conversationId: parsed.conversationId || "unknown",
  timestamp: parsed.timestamp || new Date().toISOString(),
  callDuration: parsed.callDuration || 0,

  // Contact info
  callerName: parsed.callerName || "",
  callerEmail: parsed.callerEmail || "",
  callerPhone: parsed.callerPhone || "",
  callerCompany: parsed.callerCompany || "",

  // Classification
  intent: parsed.intent || "",
  segment: parsed.segment || "",
  conversionAction: parsed.conversionAction || "",
  callOutcome: parsed.callOutcome || "",

  // Lead metadata
  leadScore: parsed.leadScore ?? 0,
  leadCategory: parsed.leadCategory || "",
  lead_type: parsed.lead_type || "",
  pipeline: parsed.pipeline || "",
  priority: parsed.priority || "",
  meeting_link: parsed.meeting_link || "",

  // Summary
  conversation_summary: parsed.conversation_summary || "",
};

// 3️⃣ Build nested qualificationData object (everything else)
const qualificationFields = [
  "purpose",
  "practice_size",
  "pain_points",
  "meetingScheduled",
  "meetingDateTime",
  "attendees",
  "family_status",
  "estate_planning_status",
  "asset_protection_concerns",
  "urgency",
  "client_count",
  "service_preference",
  "dfm_plan_type",
  "advisor_program_tier",
  "product_interest",
  "product_category",
  "purchase_intent",
  "discount_applied",
  "discount_code",
  "redirect_url",
  "issue_category",
  "issue_description",
  "support_priority",
  "callback_requested",
  "callback_time",
  "ticket_id",
  "resolution_status",
  "assigned_department",
];

// Build qualificationData dynamically
const qualificationData = {};
for (const key of qualificationFields) {
  qualificationData[key] = parsed[key] ?? "";
}

// 4️⃣ Generate tags (if not already provided)
let tags = parsed.tags;
if (!tags) {
  const tagList = [
    result.segment,
    result.intent,
    result.leadCategory,
    qualificationData.product_category,
    qualificationData.service_preference
  ].filter(Boolean);
  tags = tagList.join(",").toLowerCase();
}

// 5️⃣ Final normalized structure
return {
  ...result,
  qualificationData,
  tags,
};

/**
 * 🧠 IronClad Family – Multi-Intent Detector v6 (Fix B2C false triggers)
 * - B2B and B2C scoring only on user messages
 * - Ignores brand noise like “IronClad Family”
 */

const body = $json.body || $json;
const data = body.data || {};
const metadata = data.metadata || {};
const analysis = data.analysis || {};
const dataCollection = analysis.data_collection_results || {};

// ========== 1️⃣ Build transcript ==========
let conversationText = "";
if (Array.isArray(data.transcript)) {
  conversationText = data.transcript
    .filter(t => t.message)
    .map(t => `${t.role === "agent" ? "Agent" : "User"}: ${t.message}`)
    .join("\n");
}

const transcriptSummary = analysis.transcript_summary || "";
const purpose = dataCollection.Purpose?.value || "";
const safePurpose = purpose || "General inquiry";

const combinedText = `
${conversationText}
${transcriptSummary}
${safePurpose}
`.toLowerCase();

const userOnlyText = data.transcript
  .filter(t => t.role === "user" && t.message)
  .map(t => t.message)
  .join(" ")
  .toLowerCase();

// ========== 2️⃣ Intent scoring ==========
const scores = { SHOP: 0, B2B: 0, B2C: 0, SUPPORT: 0 };

// --- SHOP ---
if (/shop\.ironcladfamily\.com|gps|tracker|wallet|bag|order|purchase|cart|discount|store/i.test(combinedText)) scores.SHOP += 2;
if (/product|buy|checkout|family10/i.test(combinedText)) scores.SHOP++;

// --- B2B (only user)
if (/advisor|adviser|financial planner|wealth manager|practice|firm|business|company|clients|compliance|succession/i.test(userOnlyText)) scores.B2B += 3;
if (/demo|vault|team|advisor vault|b2b/i.test(userOnlyText)) scores.B2B += 2;

// --- SUPPORT
if (/error|issue|problem|login|password|reset|access|technical|support|ticket|trouble/i.test(combinedText)) scores.SUPPORT += 3;
if (/help|billing|payment|subscription|configuration|install/i.test(combinedText)) scores.SUPPORT++;

// --- B2C (only user, exclude “family”)
if (/estate|will|trust|planning|digital vault|document storage|free trial|diy|difm|inheritance/i.test(userOnlyText)) scores.B2C += 2;
if (/parents|grandparents|b2c/i.test(userOnlyText)) scores.B2C++;

// ========== 3️⃣ Pick relevant intents ==========
let intents = Object.entries(scores)
  .filter(([k, v]) => v > 1)
  .sort((a, b) => b[1] - a[1])
  .map(([k]) => k);

if (intents.length === 0) intents = ["UNKNOWN"];

// ========== 4️⃣ Clean up conflicting intents ==========
if (intents.includes("B2B")) {
  intents = intents.filter(i => i !== "B2C" && i !== "SUPPORT");
} else if (intents.includes("SHOP") && intents.includes("B2C")) {
  intents = ["SHOP", "B2C"];
} else if (intents.includes("SUPPORT") && intents.length > 1) {
  if (!/error|login|issue|password/i.test(combinedText)) {
    intents = intents.filter(i => i !== "SUPPORT");
  }
}

// 🚫 Extra safeguard: If B2C score came only from brand noise, strip it
if (intents.includes("B2C") && !/estate|will|trust|planning|inheritance|parents|grandparents/i.test(userOnlyText)) {
  intents = intents.filter(i => i !== "B2C");
}

// ========== 5️⃣ Determine primary intent ==========
let primaryIntent = "UNKNOWN";
if (intents.includes("SHOP")) primaryIntent = "SHOP";
else if (intents.includes("B2B")) primaryIntent = "B2B";
else if (intents.includes("SUPPORT")) primaryIntent = "SUPPORT";
else if (intents.includes("B2C")) primaryIntent = "B2C";

// ========== 6️⃣ Qualification Data (UTC-safe) ==========
let meetingDateTimeRaw = dataCollection["Meeting Date"]?.value || "";
if (meetingDateTimeRaw && !meetingDateTimeRaw.endsWith("Z")) {
  meetingDateTimeRaw = meetingDateTimeRaw + "Z";
}

const qd = {
  purpose: safePurpose,
  timeline: dataCollection.Timeline?.value || "",
  location: dataCollection.Location?.value || "",
  practice_size: dataCollection.practice_size?.value || "",
  client_count: dataCollection.client_count?.value || "",
  pain_points: dataCollection.pain_points?.value || "",
  family_status: dataCollection.family_status?.value || "",
  estate_planning_status: dataCollection.estate_planning_status?.value || "",
  product_interest: "",
  product_category: "",
  discount_code: "",
  discount_applied: "No",
  redirect_url: "",
  issue_category: "",
  issue_description: "",
  support_priority: "normal",
  callback_requested: "No",
  assigned_department: "",
  meetingScheduled: dataCollection["Meeting Status"]?.value || "",
  meetingDateTime: meetingDateTimeRaw
};

// ========== 7️⃣ SHOP enrichment ==========
if (intents.includes("SHOP")) {
  if (/gps.*tracker/i.test(combinedText)) {
    qd.product_interest = "GPS Tracker for Elderly";
    qd.product_category = "Trackers";
  } else if (/wallet/i.test(combinedText)) {
    qd.product_interest = "RFID Wallet";
    qd.product_category = "Wallets";
  } else if (/fireproof.*bag/i.test(combinedText)) {
    qd.product_interest = "Fireproof Document Bag";
    qd.product_category = "Bags";
  }

  if (/family10/i.test(combinedText)) {
    qd.discount_code = "FAMILY10";
    qd.discount_applied = "Yes";
  }

  const urlMatch = conversationText.match(/https:\/\/shop\.ironcladfamily\.com[^\s\])]+/);
  if (urlMatch) qd.redirect_url = urlMatch[0];
}

// ========== 8️⃣ SUPPORT enrichment ==========
if (intents.includes("SUPPORT")) {
  if (/login|password|access/i.test(combinedText)) {
    qd.issue_category = "Login/Access Issue";
    qd.assigned_department = "Technical Support";
  } else if (/billing|payment/i.test(combinedText)) {
    qd.issue_category = "Billing/Payment Issue";
    qd.assigned_department = "Billing Team";
  }
  qd.issue_description = safePurpose;
  if (/urgent|critical/i.test(combinedText)) qd.support_priority = "high";
}

// ========== 9️⃣ Return Clean Output ==========
return {
  conversationId: data.conversation_id || "unknown",
  timestamp: new Date().toISOString(),
  callDuration: metadata.call_duration_secs || 0,
  callerName: dataCollection.name?.value || "",
  firstName: dataCollection.name?.value?.split(" ")[0] || "",
  lastName: dataCollection.name?.value?.split(" ").slice(1).join(" ") || "",
  callerEmail: dataCollection.email?.value || "",
  callerPhone: dataCollection["phone number"]?.value || "",
  callerCompany: dataCollection["Caller company"]?.value || "",
  intents,
  primaryIntent,
  segment: intents.join("+"),
  conversionAction: "",
  callOutcome: dataCollection["Call Outcome"]?.value || analysis.call_successful || "",
  qualificationData: qd,
  transcript: conversationText,
  transcriptSummary,
  conversation_summary: transcriptSummary,
  tags: intents.join(",").toLowerCase(),
  debugScores: scores
};

/**
 * 🔄 IronClad Family – Intent Transition Detector v3
 * Detects if a user changed intent mid-conversation (e.g. SHOP → B2B).
 */

const intents = Array.isArray($json.intents) ? $json.intents : [$json.intents].filter(Boolean);
const transcript = ($json.transcript || "").toLowerCase();

// Filter out noisy intents
const majorIntents = intents.filter(i => !["SUPPORT", "UNKNOWN"].includes(i));
const transitions = [];

// ✅ Only check if multiple major intents exist
if (majorIntents.length > 1) {
  const firstHalf = transcript.substring(0, transcript.length / 2);
  const secondHalf = transcript.substring(transcript.length / 2);

  // SHOP → B2B
  if (majorIntents.includes("SHOP") && majorIntents.includes("B2B")) {
    const shopFirst = /\b(product|buy|purchase|gps|tracker|wallet)\b/i.test(firstHalf);
    const b2bSecond = /\b(demo|advisor|practice|compliance|client|firm)\b/i.test(secondHalf);
    if (shopFirst && b2bSecond) {
      transitions.push({ from: "SHOP", to: "B2B", pattern: "product_to_demo" });
    }
  }

  // B2C → SHOP
  if (majorIntents.includes("B2C") && majorIntents.includes("SHOP")) {
    const familyFirst = /\b(family|vault|plan|documents|will)\b/i.test(firstHalf);
    const shopSecond = /\b(buy|purchase|product|bag|tracker)\b/i.test(secondHalf);
    if (familyFirst && shopSecond) {
      transitions.push({ from: "B2C", to: "SHOP", pattern: "family_to_product" });
    }
  }

  // B2C → B2B
  if (majorIntents.includes("B2C") && majorIntents.includes("B2B")) {
    const familyFirst = /\b(family|personal|vault|documents|plan)\b/i.test(firstHalf);
    const advisorSecond = /\b(advisor|practice|firm|clients|demo|b2b)\b/i.test(secondHalf);
    if (familyFirst && advisorSecond) {
      transitions.push({ from: "B2C", to: "B2B", pattern: "consumer_to_advisor" });
    }
  }

  // B2B → SHOP (rare but valid)
  if (majorIntents.includes("B2B") && majorIntents.includes("SHOP")) {
    const demoFirst = /\b(demo|advisor|practice|firm)\b/i.test(firstHalf);
    const shopSecond = /\b(buy|purchase|product|order)\b/i.test(secondHalf);
    if (demoFirst && shopSecond) {
      transitions.push({ from: "B2B", to: "SHOP", pattern: "advisor_to_product" });
    }
  }
}

// ✅ Clean output
return {
  json: {
    ...$json,
    hasIntentTransition: transitions.length > 0,
    intentTransitions: transitions,
    transitionPattern: transitions[0]?.pattern || null,
    transitionDetails: transitions.length
      ? `${transitions.map(t => `${t.from}→${t.to}`).join(", ")}`
      : "none"
  }
};

/**
 * Decide which action to prioritize based on detected intents
 * Priority: Demo (B2B) > Consultation (B2C/DIFM) > Shop > Trial > Support
 */

const intents = $json.intents || [];
const transitions = $json.intentTransitions || [];

let primaryAction = '';
let secondaryAction = '';
let segment = '';
let transitionSummary = '';
let lead_notes = '';

/* --- PRIORITY LOGIC --- */

// If B2B involved → demo first
if (intents.includes('B2B')) {
  primaryAction = 'SCHEDULE_DEMO';
  segment = 'B2B';
  if (intents.includes('SHOP')) secondaryAction = 'SEND_SHOP_LINK';
  else if (intents.includes('B2C')) secondaryAction = 'SEND_TRIAL_INFO';
  else if (intents.includes('SUPPORT')) secondaryAction = 'CREATE_SUPPORT_TICKET';
}

// If SHOP + B2C → shop first
else if (intents.includes('SHOP') && intents.includes('B2C')) {
  primaryAction = 'SEND_SHOP_LINK';
  secondaryAction = 'OFFER_CONSULTATION';
  segment = 'SHOP';
}

// If B2C only → consultation or trial
else if (intents.includes('B2C')) {
  primaryAction = 'OFFER_CONSULTATION';
  secondaryAction = 'SEND_TRIAL_INFO';
  segment = 'B2C';
}

// If only SUPPORT
else if (intents.includes('SUPPORT')) {
  primaryAction = 'CREATE_SUPPORT_TICKET';
  segment = 'SUPPORT';
}

// Fallback
else {
  primaryAction = 'FOLLOW_PRIMARY_INTENT';
  secondaryAction = null;
  segment = $json.segment || 'UNKNOWN';
}

/* --- LOGGING / NOTES --- */
if (transitions.length > 0) {
  transitionSummary = `${transitions[0].from} → ${transitions[0].to}`;
  lead_notes = `Customer shifted from ${transitions[0].from} to ${transitions[0].to}, showing multiple needs and higher engagement.`;
} else {
  lead_notes = `Single-intent conversation with focus on ${primaryAction}.`;
}

/* --- FINAL OUTPUT --- */
return {
  json: {
    ...$json,
    primaryAction,
    secondaryAction,
    segment,
    transitionSummary,
    lead_notes,
    priority: 'HIGH',
    leadScore: ($json.leadScore || 0) + 20
  }
};

// === Get the incoming data ===
const data = $json;

// === FIX BAD EMAIL FORMATS ===
// Convert "name at domain dot com" → "name@domain.com"
function normalizeEmail(email) {
  if (!email) return '';
  return email
    .replace(/\s+at\s+/gi, '@')     // replace " at " with "@"
    .replace(/\s+dot\s+/gi, '.')    // replace " dot " with "."
    .replace(/\s+/g, '')            // remove stray spaces
    .toLowerCase();                 // normalize casing
}

// Normalize caller and attendee emails
data.callerEmail = normalizeEmail(data.callerEmail);
if (data.qualificationData?.attendees)
  data.qualificationData.attendees = normalizeEmail(data.qualificationData.attendees);

// === PARSE MEETING DATE/TIME ===
let meetingInput = data.qualificationData?.meetingDateTime || data.meetingDateTime;
if (!meetingInput) meetingInput = "Thursday at 2 PM";

let meetingDate;

if (/^\d{4}-\d{2}-\d{2}T/.test(meetingInput)) {
  // ✅ ISO 8601 style input (e.g., 2025-10-28T14:00:00-04:00)
  meetingDate = new Date(meetingInput);
} else {
  // ✅ Handle natural language format like "Thursday at 2 PM"
  const match = meetingInput.match(/(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\s*at\s*(\d{1,2})(?::(\d{2}))?\s*(AM|PM)/i);
  if (!match) {
    throw new Error("Invalid meetingDateTime format. Expected 'Thursday at 2 PM' or ISO format like '2025-10-28T14:00:00-04:00'.");
  }

  const [, dayName, hourStr, minuteStr, ampm] = match;
  let hour = parseInt(hourStr, 10);
  if (ampm.toUpperCase() === "PM" && hour !== 12) hour += 12;
  if (ampm.toUpperCase() === "AM" && hour === 12) hour = 0;
  const minute = minuteStr ? parseInt(minuteStr, 10) : 0;

  const days = { Sunday: 0, Monday: 1, Tuesday: 2, Wednesday: 3, Thursday: 4, Friday: 5, Saturday: 6 };
  const targetDay = days[dayName.charAt(0).toUpperCase() + dayName.slice(1).toLowerCase()];

  const now = new Date();
  const diff = (targetDay + 7 - now.getDay()) % 7;
  meetingDate = new Date(now);
  meetingDate.setDate(now.getDate() + diff);
  meetingDate.setHours(hour, minute, 0, 0);
}

// === ENFORCE BUSINESS DAY AND TIME RULES ===

// 1️⃣ Skip Friday (5), Saturday (6), Sunday (0)
while ([5, 6, 0].includes(meetingDate.getDay())) {
  meetingDate.setDate(meetingDate.getDate() + 1);
  meetingDate.setHours(9, 0, 0, 0);
}

// 2️⃣ Enforce business hours (9 AM – 5 PM ET)
if (meetingDate.getHours() < 9) {
  meetingDate.setHours(9, 0, 0, 0);
} else if (meetingDate.getHours() >= 17) {
  meetingDate.setDate(meetingDate.getDate() + 1);
  meetingDate.setHours(9, 0, 0, 0);
  while ([5, 6, 0].includes(meetingDate.getDay())) {
    meetingDate.setDate(meetingDate.getDate() + 1);
  }
}

// === CONVERT EASTERN → UTC ===
const easternStr = meetingDate.toLocaleString("en-US", { timeZone: "America/New_York" });
const easternDate = new Date(easternStr);
const startUTC = new Date(easternDate.toLocaleString("en-US", { timeZone: "UTC" }));

// Create 30-minute end time
const endUTC = new Date(startUTC.getTime() + 30 * 60 * 1000);

// === RETURN FOR n8n ===
return [
  {
    json: {
      ...data,
      calendarEvent: {
        summary: `Consultation Call - ${data.callerName || "Prospect"}`,
        description: `IronClad Family Consultation\n\nName: ${data.callerName}\nEmail: ${data.callerEmail}\nPhone: ${data.callerPhone}\nCompany: ${data.callerCompany}\nAttendees: ${data.qualificationData?.attendees || data.callerName}\n\nPurpose: ${data.qualificationData?.purpose || "Consultation call"}`,
        startDateTime: startUTC.toISOString(),
        endDateTime: endUTC.toISOString(),
        attendeeEmail: data.callerEmail,
        timeZone: "America/New_York"
      }
    }
  }
];

