  const targetDay = days[dayName.charAt(0).toUpperCase() + dayName.slice(1).toLowerCase()];

  // Find next occurrence of that weekday
  const now = new Date();
  const diff = (targetDay + 7 - now.getDay()) % 7;
  meetingDate = new Date(now);
  meetingDate.setDate(now.getDate() + diff);
  meetingDate.setHours(hour, minute, 0, 0);
}

// === ENFORCE BUSINESS DAY AND TIME RULES ===

