  meetingDate.setDate(meetingDate.getDate() + 1);
  meetingDate.setHours(9, 0, 0, 0);
}

// 2️⃣ Enforce business hours (9 AM – 5 PM ET)
if (meetingDate.getHours() < 9) {
  meetingDate.setHours(9, 0, 0, 0);
} else if (meetingDate.getHours() >= 17) {
  meetingDate.setDate(meetingDate.getDate() + 1);
  meetingDate.setHours(9, 0, 0, 0);
  while ([5, 6, 0].includes(meetingDate.getDay())) {
    meetingDate.setDate(meetingDate.getDate() + 1);
  }
}

// === CONVERT EASTERN → UTC ===
const easternStr = meetingDate.toLocaleString("en-US", { timeZone: "America/New_York" });
const easternDate = new Date(easternStr);
const startUTC = new Date(easternDate.toLocaleString("en-US", { timeZone: "UTC" }));

// Create 30-minute end time
const endUTC = new Date(startUTC.getTime() + 30 * 60 * 1000);

// === RETURN FOR n8n ===
return [
  {
    json: {
      ...data,
      calendarEvent: {
        summary: `Consultation Call - ${data.callerName || "Prospect"}`,
        description: `IronClad Family Consultation\n\nName: ${data.callerName}\nEmail: ${data.callerEmail}\nPhone: ${data.callerPhone}\nCompany: ${data.callerCompany}\nAttendees: ${data.qualificationData?.attendees || data.callerName}\n\nPurpose: ${data.qualificationData?.purpose || "Consultation call"}`,
        startDateTime: startUTC.toISOString(),
        endDateTime: endUTC.toISOString(),
