// Parse webhook request
const body = $input.item.json.body || {};

// Get parameters with defaults
const action = body.action || 'findSlots';
const now = new Date();
const startDate = body.startDate || now.toISOString();
const endDate = body.endDate || new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString();

// Handle specific time check
if (action === 'checkTime' && body.checkDate) {
  const checkTime = new Date(body.checkDate);
  const rangeStart = new Date(checkTime.getTime() - 2 * 60 * 60 * 1000); // 2 hours before
  const rangeEnd = new Date(checkTime.getTime() + 2 * 60 * 60 * 1000);   // 2 hours after

  return {
    action: 'checkTime',
    timeMin: rangeStart.toISOString(),
    timeMax: rangeEnd.toISOString(),
    checkSpecificTime: body.checkDate,
    duration: body.duration || 30,
    includeWeekends: body.includeWeekends || false
  };
}

// Return date range for finding slots
return {
  action: 'findSlots',
  timeMin: startDate,
  timeMax: endDate,
  duration: body.duration || 30,
  includeWeekends: body.includeWeekends || false
};

// Get all events and request data
const events = $input.all().map(item => item.json);
const requestData = $('Parse Request').first().json;

// Check specific time availability
if (requestData.action === 'checkTime') {
  const requestedTime = new Date(requestData.checkSpecificTime);
  const conflicts = events.filter(event => {
    if (!event.start || !event.end) return false;

    const eventStart = new Date(event.start.dateTime || event.start.date);
    const eventEnd = new Date(event.end.dateTime || event.end.date);

    return requestedTime >= eventStart && requestedTime < eventEnd;
  });

  return {
    action: 'checkTime',
    available: conflicts.length === 0,
    requestedTime: requestData.checkSpecificTime,
    conflicts: conflicts.map(e => ({
      title: e.summary || 'Busy',
      start: e.start.dateTime || event.start.date,
      end: e.end.dateTime || event.end.date
    }))
  };
}

// Find available slots
const slots = [];
const businessHours = { start: 9, end: 17 }; // 9 AM to 5 PM
const slotDuration = requestData.duration;
const now = new Date();

// Check next 14 days
for (let day = 0; day < 14 && slots.length < 10; day++) {
  const date = new Date(now);
  date.setDate(date.getDate() + day);

  // Skip weekends if not included
  if (!requestData.includeWeekends && (date.getDay() === 0 || date.getDay() === 6)) {
    continue;
  }

  // Check each time slot
  for (let hour = businessHours.start; hour < businessHours.end; hour++) {
    for (let minute = 0; minute < 60; minute += slotDuration) {
      const slotStart = new Date(date);
      slotStart.setHours(hour, minute, 0, 0);

      if (slotStart <= now) continue;

      const slotEnd = new Date(slotStart.getTime() + slotDuration * 60 * 1000);

      // Check if slot is free
      const isBooked = events.some(event => {
        if (!event.start || !event.end) return false;

        const eventStart = new Date(event.start.dateTime || event.start.date);
        const eventEnd = new Date(event.end.dateTime || event.end.date);

        return (
          (slotStart >= eventStart && slotStart < eventEnd) ||
          (slotEnd > eventStart && slotEnd <= eventEnd) ||
          (slotStart <= eventStart && slotEnd >= eventEnd)
        );
      });

      if (!isBooked && slots.length < 10) {
        slots.push({
          start: slotStart.toISOString(),
          end: slotEnd.toISOString(),
          display: slotStart.toLocaleString('en-US', {
            weekday: 'short',
            month: 'short',
            day: 'numeric',
            hour: 'numeric',
            minute: '2-digit',
            hour12: true
          })
        });
      }
    }
  }
}

return {
  action: 'findSlots',
  availableSlots: slots,
  totalFound: slots.length,
  searchRange: {
    start: requestData.timeMin,
    end: requestData.timeMax
  }
};

// Format final response
const data = $input.item.json;

if (data.action === 'checkTime') {
  return {
    success: true,
    action: 'checkTime',
    result: {
      available: data.available,
      requestedTime: data.requestedTime,
      message: data.available 
        ? 'The requested time slot is available' 
        : `Time slot is busy. Conflicts with: ${data.conflicts.map(c => c.title).join(', ')}`
    }
  };
}

// Format findSlots response
return {
  success: true,
  action: 'findSlots',
  result: {
    totalSlots: data.totalFound,
    slots: data.availableSlots,
    nextAvailable: data.availableSlots[0]?.display || 'No slots available',
    message: data.totalFound > 0 
      ? `Found ${data.totalFound} available slots` 
      : 'No available slots found in the next 2 weeks'
  }
};
